CREATE SCHEMA IF NOT EXISTS sync;

ALTER TABLE app."Attendance"
    ADD COLUMN IF NOT EXISTS "SyncVersion" BIGINT NOT NULL DEFAULT 1;

CREATE TABLE IF NOT EXISTS sync."MobileDevice"
(
    "MobileDeviceId" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "DeviceGuid" UUID NOT NULL,
    "CompanyId" BIGINT NOT NULL,
    "UserId" BIGINT NOT NULL,
    "LastSeenAt" TIMESTAMPTZ NOT NULL,
    "StatusId" INT NOT NULL DEFAULT 1,
    "CreatedById" BIGINT NOT NULL DEFAULT 0,
    "CreatedTime" TIMESTAMPTZ NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
    "UpdatedById" BIGINT,
    "UpdatedTime" TIMESTAMPTZ,
    "DeletedById" BIGINT,
    "DeletedTime" TIMESTAMPTZ,
    CONSTRAINT "UQ_MobileDevice_DeviceTenantUser" UNIQUE ("DeviceGuid", "CompanyId", "UserId")
);

CREATE INDEX IF NOT EXISTS "IX_MobileDevice_TenantUser"
    ON sync."MobileDevice" ("CompanyId", "UserId");

CREATE TABLE IF NOT EXISTS sync."MobileSyncBatch"
(
    "MobileSyncBatchId" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "BatchGuid" UUID NOT NULL,
    "DeviceGuid" UUID NOT NULL,
    "CompanyId" BIGINT NOT NULL,
    "UserId" BIGINT NOT NULL,
    "ClientCreatedAt" TIMESTAMPTZ NOT NULL,
    "Status" VARCHAR(20) NOT NULL,
    "CompletedTime" TIMESTAMPTZ,
    "StatusId" INT NOT NULL DEFAULT 1,
    "CreatedById" BIGINT NOT NULL DEFAULT 0,
    "CreatedTime" TIMESTAMPTZ NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
    "UpdatedById" BIGINT,
    "UpdatedTime" TIMESTAMPTZ,
    "DeletedById" BIGINT,
    "DeletedTime" TIMESTAMPTZ,
    CONSTRAINT "UQ_MobileSyncBatch_BatchTenantUser" UNIQUE ("BatchGuid", "CompanyId", "UserId")
);

CREATE INDEX IF NOT EXISTS "IX_MobileSyncBatch_Device"
    ON sync."MobileSyncBatch" ("DeviceGuid", "CompanyId", "UserId");

CREATE TABLE IF NOT EXISTS sync."MobileSyncOperation"
(
    "MobileSyncOperationId" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "OperationGuid" UUID NOT NULL,
    "BatchGuid" UUID NOT NULL,
    "CompanyId" BIGINT NOT NULL,
    "UserId" BIGINT NOT NULL,
    "EntityType" VARCHAR(80) NOT NULL,
    "OperationType" VARCHAR(80) NOT NULL,
    "EntityGuid" UUID NOT NULL,
    "BaseVersion" BIGINT,
    "Status" VARCHAR(20) NOT NULL,
    "ReceiptJson" JSONB,
    "ProcessedTime" TIMESTAMPTZ,
    "StatusId" INT NOT NULL DEFAULT 1,
    "CreatedById" BIGINT NOT NULL DEFAULT 0,
    "CreatedTime" TIMESTAMPTZ NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
    "UpdatedById" BIGINT,
    "UpdatedTime" TIMESTAMPTZ,
    "DeletedById" BIGINT,
    "DeletedTime" TIMESTAMPTZ,
    CONSTRAINT "UQ_MobileSyncOperation_OperationTenantUser" UNIQUE ("OperationGuid", "CompanyId", "UserId")
);

CREATE INDEX IF NOT EXISTS "IX_MobileSyncOperation_Batch"
    ON sync."MobileSyncOperation" ("BatchGuid", "CompanyId", "UserId", "MobileSyncOperationId");

CREATE INDEX IF NOT EXISTS "IX_MobileSyncOperation_Entity"
    ON sync."MobileSyncOperation" ("EntityType", "EntityGuid", "CompanyId");
